"""Explain modular per-CPU counts and writer admission."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1421': ('들어온 문과 나간 문이 다른 도서관을 생각해 봅시다. 문마다 적은 출입 차이는 달라도 전체를 더하면 남은 사람 수를 알 수 있습니다.', 'CPU 이동 뒤의 unsigned 카운터와 전체 합계 원리를 배웁니다.', 'CPU 0에서 입장하여 [1,0], CPU 1에서 퇴장하여 [1,0xffffffff]라고 적으세요. 32비트 합계는 0이므로 남은 독자는 없다는 계산을 하세요.', ['읽기 획득과 해제는 각각 짧게 선점을 제어합니다. 그 사이 실제 읽기 보유 구간 전체가 같은 CPU에 고정되지는 않습니다. 따라서 CPU 0에서 증가한 작업이 CPU 1에서 감소할 수 있습니다.', '카운터는 unsigned int입니다. 부호 없는 32비트 값은 0에서 하나 빼면 0xffffffff가 됩니다. 이를 음수 사람이 실제로 있다는 뜻으로 읽지 마세요. 각 CPU의 기록은 전체 균형을 맞추는 출입 차이입니다.', 'per_cpu_sum의 __sum은 typeof(var), 즉 원래 카운터와 같은 타입입니다. for_each_possible_cpu로 가능한 CPU의 기록들을 더합니다. 계산도 같은 비트 폭 안에서 이루어져 넘친 높은 자리는 남지 않습니다.', 'CPU 0의 1과 CPU 1의 0xffffffff를 더하면 수학적으로 0x100000000입니다. 그러나 32비트 합에는 낮은 32칸만 남으므로 0입니다. 0xffffffff는 2의 32제곱보다 1 작은 수여서, 1과 합치면 한 바퀴 돌아 0이 됩니다.', '이처럼 일정 범위에서 돌아가는 계산을 모듈러 합이라고 합니다. 개별 CPU 값이 모두 0이어야 전체 독자가 없는 것은 아닙니다. 실패한 읽기 시도의 즉시 취소는 같은 CPU에서 하지만, 정상 보유 후 반납은 다른 CPU일 수 있다는 차이도 기억하세요.', '합계가 실제 활동 수를 나타내려면 전체 활동 규모가 표현 범위를 돌아 0이 될 정도로 커지지 않는 조건이 필요합니다. 또한 CPU들을 순서대로 읽는 행위가 그 자체로 전역 순간 사진을 만드는 것은 아닙니다. writer의 차단·전환·배리어 규칙과 함께 해석해야 합니다.'], [('32비트 unsigned 합계에서 1+0xffffffff는 무엇일까요?', ['항상 0x100000000 전체를 저장해요', '0이에요'], '합의 저장 폭도 32비트라 33번째 비트는 남지 않습니다. 낮은 32비트가 모두 0이므로 전체 출입 차이가 상쇄됩니다.'), ('읽기 보유 시간 전체에 걸쳐 CPU 이동이 금지될까요?', ['아니요. 짧은 증가·감소 구간을 각각 보호해요', '네. 언제나 획득한 CPU에서만 반납해요'], 'down_read는 반환 전에 선점 제어를 되돌립니다. 읽다가 CPU가 바뀔 수 있으므로 전체 카운터 합으로 균형을 계산하는 설계입니다.')]), 'os1422': ('읽는 사람이 있는지 묻는 표시등이 인원뿐 아니라 출입문 상태도 함께 본다면, 불이 꺼졌다고 인원이 꼭 0인 것은 아닙니다.', '두 조건을 함께 검사하는 상태 조회와 소유권을 구별합니다.', '합계 0·block 0 → false, 합계 1·block 0 → true, 합계 1·block 1 → false를 쓰세요. 마지막 줄에는 독자가 남아 있다고 덧붙이세요.', ['percpu_is_read_locked는 두 조건을 &&로 연결합니다. &&는 둘 다 참이어야 참이라는 뜻입니다. 첫 조건은 CPU별 카운터 합이 0이 아닌지이고, 둘째는 block이 0인지입니다.', '!atomic_read(&sem->block)의 !는 참·거짓을 뒤집습니다. block=0이면 이 조건은 참이고 block=1이면 거짓입니다. 합계가 1이어도 block=1이면 전체 식은 false입니다.', 'writer가 새 독자를 막으려고 block을 1로 만든 뒤 기존 독자가 끝나기를 기다리는 시간이 있습니다. 그때는 독자가 남아 있어도 is_read_locked가 false일 수 있습니다. false를 독자 수 0의 증거로 쓰면 잘못입니다.', 'percpu_is_write_locked는 block 값을 읽습니다. 이 또한 현재 호출한 작업의 이름이나 소유자 번호를 검사하지 않습니다. 다른 writer가 차단을 차지했을 수 있습니다.', 'block=1은 writer가 차단을 확보했다는 상태이고, 기존 독자를 모두 기다렸는지까지 이 조회 하나가 알려 주지는 않습니다. 실제 쓰기 권한 획득은 down_write의 전체 절차와 함께 판단해야 합니다.', '이런 조회는 상태 확인용이며 잠금 획득을 대신하지 않습니다. 여러 값을 읽는 사이 상태가 달라질 수도 있습니다. true나 false를 봤다는 이유만으로 보호 자료를 잠금 없이 읽거나 쓰지 말고 정해진 획득·해제 API를 따르세요.'], [('카운터 합이 1이고 block도 1이면 is_read_locked는 무엇일까요?', ['언제나 true예요', 'false예요'], '합계가 0이 아니어도 !block이 거짓이므로 && 전체는 거짓입니다. 이 예시는 false여도 독자가 남아 있을 수 있음을 보여 줍니다.'), ('is_write_locked의 참이 현재 작업의 소유권을 증명할까요?', ['아니요. block 상태를 읽는 것뿐이에요', '네. 조회한 작업이 언제나 writer예요'], '소유자 이름을 기록하거나 비교하는 코드가 없습니다. 다른 작업이 차단을 잡았을 수 있으며, 조회만으로 쓰기 권한을 얻지 않습니다.')]), 'os1423': ('새 독자의 입장을 막은 뒤 안에 남은 사람이 모두 나가기를 기다립니다. 사람 수만 0이라고 보는 것에 더해, 그들의 작업이 끝난 순서도 맞춰야 합니다.', 'writer의 독자 대기 종료 조건과 메모리 배리어를 이해합니다.', 'block 설정 → 합계가 남으면 기다림 → 합계 0 확인 → C 배리어 → true 순서를 그리세요. block 없이 순간 0만 보는 경우와 구별하세요.', ['readers_active_check는 writer가 기존 독자들의 종료를 확인할 때 쓰는 내부 함수입니다. 원문 주석은 block이 이미 설정되어 있다고 가정합니다. 아무 문맥에서 0만 찾는 일반 검색 함수로 사용하면 안 됩니다.', 'per_cpu_sum으로 CPU별 기록의 모듈러 합을 계산합니다. 합이 0이 아니면 아직 종료 조건이 아니므로 false입니다. 각 CPU의 원소가 전부 0인지 따로 요구하는 것은 아닙니다.', '합계가 0이면 smp_mb를 실행하고 true를 반환합니다. 원문에서 C라고 표시한 메모리 배리어입니다. 배리어는 단순히 잠시 쉬는 명령이 아니라 CPU 사이의 접근 순서를 맞추는 장치입니다.', '독자 해제의 B 배리어는 작업 후 카운터를 낮추는 순서에 있고, writer의 C는 그 감소를 본 다음에 있습니다. writer가 마지막 감소를 관측했다면 앞선 읽기 보호 구간의 접근도 끝난 순서로 이어져야 합니다.', '새로 온 느린 독자는 임시로 카운터를 올리더라도 block을 보면 같은 CPU에서 즉시 취소합니다. 쓰기 전환과 배리어 규칙 아래 새 독자가 보호 구간을 통과하지 못하므로 합계 0을 종료 조건으로 사용할 수 있습니다.', '순간 0이 보였다는 것만으로 어디서나 안전한 것은 아닙니다. writer의 RCU-sync 전환, block 설정, 독자 쪽 취소와 해제 규칙이 함께 필요합니다. 숫자 예시를 맞혔다고 하드웨어의 모든 동시 실행 순서를 검증한 것은 아닙니다.'], [('readers_active_check를 사용하는 원문의 전제는 무엇일까요?', ['block이 0이면 어디서나 안전해요', 'writer가 block을 설정한 상태예요'], '새 독자가 차단을 보고 취소하는 규칙이 필요합니다. block 없이 순간 합계 0을 읽으면 그 뒤 새 독자가 바로 들어올 수 있습니다.'), ('합계 0 뒤의 C 배리어는 어떤 접근과 연결될까요?', ['종료한 reader의 앞선 보호 구간 접근이에요', '아직 오지 않은 모든 reader의 미래 쓰기예요'], '독자 감소 전에 있는 B 배리어와 연결해, 감소를 본 writer가 앞선 보호 구간 뒤에 진행하도록 합니다. 임의의 미래 작업까지 보장하는 것은 아닙니다.')]), 'os1424': ('비어 있는 예약표를 봤어도 예약 도장을 찍기 전에 다른 사람이 먼저 찍을 수 있습니다. 최종 성공은 실제로 표를 바꾸는 순간의 옛 값으로 판단합니다.', 'writer의 빠른 조회와 원자적 교환을 구별합니다.', 'A와 B가 모두 block=0을 읽었다고 적으세요. B의 교환은 이전 0을 받아 성공, 뒤의 A는 이전 1을 받아 실패합니다. 최종 block은 1입니다.', ['__percpu_down_write_trylock은 먼저 atomic_read로 block을 봅니다. 이미 1이면 바로 false를 반환합니다. 바쁜 것이 보이면 굳이 원자적 교환까지 시도하지 않는 짧은 경로입니다.', '0을 보았다면 atomic_xchg(&sem->block,1)를 합니다. xchg는 현재 값을 1로 바꾸며 바꾸기 전 값을 돌려주는 원자적 교환입니다. 비교를 하는 CAS와 달리 교환 자체는 지정 값 1을 저장합니다.', '돌려받은 이전 값이 0이면 자신이 빈 차단 표시를 차지했으므로 true입니다. 이전 값이 1이면 다른 writer가 이미 차지했으므로 false입니다. 성공 여부를 최종 판단하는 것은 이 이전 값입니다.', 'A가 0을 읽은 뒤 B가 먼저 1로 바꾸면 A의 교환은 이전 값 1을 받습니다. 처음 조회가 0이었다고 성공이 보장되지는 않습니다. 두 writer가 동시에 성공했다고 판단하지 않도록 원자적 교환을 사용합니다.', 'block에는 카운터 합이 아니라 차단 상태 1을 씁니다. 새 reader의 느린 경로가 이 상태를 보고 진입을 취소합니다. writer의 교환 쪽 D 순서는 reader 증가 뒤의 A 배리어와 함께 서로의 진입을 놓치지 않도록 연결됩니다.', '이 내부 시도에 성공한 것만으로 기존 독자가 모두 끝난 것은 아닙니다. 바깥 down_write는 RCU-sync 전환을 하고 차단을 얻은 뒤 기존 독자 합계가 0이 되기를 기다립니다. 차단 확보와 실제 쓰기 시작까지의 전체 절차를 구별하세요.'], [('처음 block=0을 읽으면 뒤의 교환도 반드시 이전 값 0을 받을까요?', ['네. 이미 성공이 확정됐어요', '아니요. 그사이에 다른 writer가 먼저 차지할 수 있어요'], '처음 읽기와 교환 사이에는 다른 실행이 들어올 수 있습니다. 최종 성공은 atomic_xchg가 돌려준 이전 값이 0인지로 판정합니다.'), ('writer의 교환은 block에 어떤 값을 저장할까요?', ['1을 저장해요', '항상 전체 reader 수를 저장해요'], 'block은 차단 표시입니다. 기존 독자 수는 read_count의 합에서 따로 확인하므로 두 역할을 섞으면 안 됩니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_351.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
